Search for issues (bugs, vulnerabilities, code smells) in my organization's projects. Filter by severities=['HIGH','BLOCKER'] for critical issues, impactSoftwareQualities=['SECURITY'] for security, issueStatuses=['OPEN'] to exclude resolved.

exec tool declaration:
```ts
declare const tools: { mcp__sonarqube__search_sonar_issues_in_projects(args: {
  // Branch name for branch-based analysis. Discover names with list_branches. For pull request analysis, use pullRequest instead.
  branch?: string;
  // An optional list of component keys (files, directories, modules) to filter issues
  files?: Array<string>;
  // An optional list of software qualities to filter by
  impactSoftwareQualities?: Array<"MAINTAINABILITY" | "RELIABILITY" | "SECURITY">;
  // An optional list of issue keys to fetch specific issues
  issueKey?: Array<string>;
  // An optional list of issue statuses to filter by. Note: IN_SANDBOX is valid only for SonarQube Server
  issueStatuses?: Array<"OPEN" | "CONFIRMED" | "FALSE_POSITIVE" | "ACCEPTED" | "FIXED" | "IN_SANDBOX">;
  // An optional 1-based page index. Defaults to 1.
  pageIndex?: number;
  // An optional page size. Must be greater than 0 and less than or equal to 500. Defaults to 100.
  pageSize?: number;
  // An optional list of SonarQube project keys to look in
  projectKeys?: Array<string>;
  // Pull request key/ID in SonarQube for PR-decorated analysis. Use list_pull_requests to discover valid keys. For branch-based analysis (long-lived or short-lived without PR), use branch instead. Must be the SonarQube PR key, not a git branch name.
  pullRequest?: string;
  // An optional list of severities to filter by
  severities?: Array<"INFO" | "LOW" | "MEDIUM" | "HIGH" | "BLOCKER">;
}): Promise<CallToolResult<{
  // List of issues found in the search
  issues: Array<{
  // Author who introduced the issue
  author: string;
  // Clean code attribute associated with the issue
  cleanCodeAttribute: string;
  // Clean code attribute category
  cleanCodeAttributeCategory: string;
  // Component (file) where the issue is located
  component: string;
  // Date when the issue was created
  creationDate: string;
  // Unique issue identifier
  key: string;
  // Issue description message
  message: string;
  // Project key where the issue was found
  project: string;
  // Rule that triggered the issue
  rule: string;
  // Issue severity level
  severity: string;
  // Current status of the issue
  status: string;
  // Location of the issue in the source file
  textRange?: {
  // Ending line number
  endLine: number;
  // Starting line number
  startLine: number;
};
}>;
  // Pagination information for the results
  paging: {
  // Current page index (1-based)
  pageIndex: number;
  // Number of items per page
  pageSize: number;
  // Total number of items across all pages
  total: number;
};
}>>; };
```"},{"name":"mcp__sonarqube__show_rule","description":"Transform your code quality workflow with SonarQube integration. Analyze code, monitor project health, investigate issues, and understand quality gates. Note: Analyzers are being downloaded in the background and will be available shortly for code analysis.
